// Arma 2 graficos (kilos por maquina y errores por operario) del trimestre que acaba de cerrar.
// Se ejecuta el dia 1 de enero/abril/julio/octubre, asi que mira los 3 meses anteriores.
const bob = $input.all().map(i => i.json);

const hoy = new Date();
const meses = [];
for (let i = 3; i >= 1; i--) meses.push(new Date(hoy.getFullYear(), hoy.getMonth() - i, 1));
const claveMes = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
const nombreMes = d => ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'][d.getMonth()] + ' ' + String(d.getFullYear()).slice(2);
const claves = meses.map(claveMes);
const labels = meses.map(nombreMes);
const qNum = Math.floor(meses[0].getMonth() / 3) + 1;
const tituloTrimestre = 'Trimestre ' + qNum + ' ' + meses[0].getFullYear() + '  (' + labels.join(' - ') + ')';

const bq = bob.filter(b => claves.includes((b.fecha || '').slice(0, 7)));

const maquinas = [...new Set(bq.map(b => b.maquina || 'S/D'))];
const seriesKilos = maquinas.map(maq => ({
  nombre: 'Maquina ' + maq,
  data: claves.map(c => bq.filter(b => (b.maquina || 'S/D') === maq && (b.fecha || '').slice(0, 7) === c)
    .reduce((a, b) => a + (Number(b.peso) || 0), 0))
}));

const operarios = [...new Set(bq.filter(b => b.estado === 'MAL').map(b => b.operario_bobina || 'S/D'))];
const seriesErrores = operarios.map(op => ({
  nombre: op,
  data: claves.map(c => bq.filter(b => (b.operario_bobina || 'S/D') === op && b.estado === 'MAL' && (b.fecha || '').slice(0, 7) === c).length)
}));

// Paleta profesional (azules/verdes/naranjas), estilo Chart.js v2 (sintaxis que usa QuickChart por defecto).
const colores = ['#1d4ed8', '#059669', '#d97706', '#dc2626', '#7c3aed', '#0891b2', '#65a30d', '#db2777'];

function config(titulo, series, yLabel) {
  return {
    type: 'line',
    data: {
      labels,
      datasets: series.map((s, i) => ({
        label: s.nombre,
        data: s.data,
        borderColor: colores[i % colores.length],
        backgroundColor: colores[i % colores.length],
        pointBackgroundColor: colores[i % colores.length],
        pointBorderColor: '#ffffff',
        pointBorderWidth: 2,
        pointRadius: 5,
        pointHoverRadius: 6,
        borderWidth: 3,
        fill: false,
        tension: 0.25
      }))
    },
    options: {
      title: {
        display: true,
        text: [titulo, tituloTrimestre],
        fontSize: 20,
        fontStyle: 'bold',
        fontColor: '#1f2937',
        padding: 18
      },
      legend: {
        display: true,
        position: 'bottom',
        labels: { fontSize: 13, fontColor: '#374151', boxWidth: 16, padding: 16 }
      },
      layout: { padding: { left: 12, right: 24, top: 4, bottom: 8 } },
      scales: {
        xAxes: [{
          scaleLabel: { display: true, labelString: 'Mes', fontSize: 13, fontColor: '#4b5563' },
          gridLines: { display: false },
          ticks: { fontSize: 13, fontColor: '#374151' }
        }],
        yAxes: [{
          scaleLabel: { display: true, labelString: yLabel, fontSize: 13, fontColor: '#4b5563' },
          ticks: { beginAtZero: true, fontSize: 12, fontColor: '#374151' },
          gridLines: { color: '#e5e7eb', drawBorder: false }
        }]
      }
    }
  };
}

const url = c => 'https://quickchart.io/chart?w=900&h=500&bkg=white&devicePixelRatio=2&c=' + encodeURIComponent(JSON.stringify(c));

const out = [];
if (seriesKilos.length) out.push({ json: { caption: 'Kilos totales de bobinas por maquina\n' + tituloTrimestre, url: url(config('Kilos totales de bobinas por maquina', seriesKilos, 'Kilos')) } });
if (seriesErrores.length) out.push({ json: { caption: 'Errores por operario\n' + tituloTrimestre, url: url(config('Errores por operario', seriesErrores, 'Cantidad de errores')) } });
return out;
